              componentDownloadIdParameter.ParameterName = "componentDownloadId";
              componentDownloadIdParameter.Direction = ParameterDirection.Input;
              componentDownloadIdParameter.Value = componentDownloadId;
              cmd.Parameters.Add(componentDownloadIdParameter);

              using (IDataReader reader = cmd.ExecuteReader()) {
